def choose_move(observation):
    # Basic deterministic: try to move toward nearest resource if safe, else toward goal of staying.
    grid_w = observation.get("grid_width", 0)
    grid_h = observation.get("grid_height", 0)
    pos = observation.get("self_position", {"x":0,"y":0})
    x = pos.get("x", 0)
    y = pos.get("y", 0)
    resources = observation.get("resources", [])
    obstacles = observation.get("obstacles", [])
    remaining = observation.get("remaining_resource_count", 0)
    scores = observation.get("scores", {})
    self_path = observation.get("self_path", [])
    opponent_path = observation.get("opponent_path", [])
    opp = observation.get("opponent_position", {"x": x, "y": y})

    def blocked(nx, ny):
        if nx < 0 or ny < 0 or nx >= grid_w or ny >= grid_h:
            return True
        for o in obstacles:
            if o.get("x") == nx and o.get("y") == ny:
                return True
        return False

    # Try simple: move to a resource if adjacent or within 1 step, else stay safe
    best_move = (0, 0)
    best_score = -10

    # If resource adjacent, go there
    for dx in (-1, 0, 1):
        for dy in (-1, 0, 1):
            if dx == 0 and dy == 0:
                continue
            nx, ny = x + dx, y + dy
            if blocked(nx, ny):
                continue
            for r in resources:
                rx = r.get("x", x)
                ry = r.get("y", y)
                if nx == rx and ny == ry:
                    best_move = (dx, dy)
                    best_score = 100
                    break
            if best_score == 100:
                break
        if best_score == 100:
            break

    if best_score != 100:
        # Move toward nearest resource if any, else away from opponent
        if resources:
            def dist(a, b):
                return abs(a[0]-b[0]) + abs(a[1]-b[1])
            nearest = None
            min_d = 10**9
            for r in resources:
                d = dist((x,y), (r.get("x", x), r.get("y", y)))
                if d < min_d:
                    min_d = d
                    nearest = (r.get("x", x), r.get("y", y))
            if nearest is not None:
                dx = 1 if nearest[0] > x else (-1 if nearest[0] < x else 0)
                dy = 1 if nearest[1] > y else (-1 if nearest[1] < y else 0)
                if not blocked(x+dx, y+dy):
                    return [dx, dy]

        # Else try to move away from opponent if possible
        ox = opp.get("x", x)
        oy = opp.get("y", y)
        dx = 1 if ox < x else (-1 if ox > x else 0)
        dy = 1 if oy < y else (-1 if oy > y else 0)
        if not blocked(x+dx, y+dy):
            return [dx, dy]

    # Fallback: try any safe neighbor, prefer staying
    for dx in (0, -1, 1):
        for dy in (0, -1, 1):
            if dx == 0 and dy == 0:
                continue
            nx, ny = x+dx, y+dy
            if not blocked(nx, ny):
                return [dx, dy]

    return [0, 0]
